actions:
  checkout_book:
    method: POST
    path: /loans/checkout
    description: Check a book out to a member. Active loan due in 21 days.
    input:
      book_id:
        type: ref
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: book
        onDelete: restrict
      member_id:
        type: ref
        required: true
        nullable: false
        unique: false
        readonly: false
        entity: member
        onDelete: restrict
    handler: |-
      (ctx) => {
        const book = ctx.db.get('book', ctx.body.book_id);
        if (book === null) ctx.fail(404, 'not_found', 'book ' + ctx.body.book_id + ' not found');
        const member = ctx.db.get('member', ctx.body.member_id);
        if (member === null) ctx.fail(404, 'not_found', 'member ' + ctx.body.member_id + ' not found');
        if (member.status === 'suspended') ctx.fail(409, 'member_suspended', 'member ' + member.id + ' is suspended');
        const open = (l) => l.status === 'active' || l.status === 'overdue';
        const mine = ctx.db.list('loan', { where: { member_id: member.id } });
        if (mine.filter(open).length >= 5) ctx.fail(409, 'loan_limit', 'member ' + member.id + ' already has 5 open loans');
        let unpaid = 0;
        for (const l of mine) {
          if ((l.status === 'returned' || l.status === 'overdue') && !l.fine_paid) unpaid += l.fine_cents;
        }
        if (unpaid >= 1000) ctx.fail(409, 'unpaid_fines', 'member ' + member.id + ' has ' + unpaid + ' cents of unpaid fines');
        const bookLoans = ctx.db.list('loan', { where: { book_id: book.id } }).filter(open);
        if (bookLoans.length >= book.copies) ctx.fail(409, 'no_copies_available', 'no copies of book ' + book.id + ' are available');
        const n = ctx.db.list('loan').length + 1;
        const ref = 'L' + ('00000' + n).slice(-5);
        const now = ctx.now();
        const loan = ctx.db.create('loan', { loan_ref: ref, book_id: book.id, member_id: member.id, borrowed_at: now, due_at: ctx.time.plus(now, '21d'), returned_at: null, status: 'active', renewals: 0, fine_cents: 0, fine_paid: false });
        return { status: 201, body: loan };
      }
  return_loan:
    method: POST
    path: /loans/{id}/return
    description: Return an active or overdue loan and fix the fine.
    input: {}
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const l = ctx.db.get('loan', id);
        if (l === null) ctx.fail(404, 'not_found', 'loan ' + id + ' not found');
        if (l.status !== 'active' && l.status !== 'overdue') ctx.fail(409, 'invalid_state', 'loan ' + id + ' is ' + l.status + '. Only active or overdue loans can be returned.');
        const now = ctx.now();
        const mins = ctx.time.minutesBetween(l.due_at, now);
        const days = mins > 0 ? Math.floor(mins / 1440) : 0;
        const fine = Math.min(2000, days * 25);
        const updated = ctx.db.update('loan', id, { status: 'returned', returned_at: now, fine_cents: fine });
        return { status: 200, body: updated };
      }
  renew_loan:
    method: POST
    path: /loans/{id}/renew
    description: Renew an active loan for 14 days, at most twice.
    input: {}
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const l = ctx.db.get('loan', id);
        if (l === null) ctx.fail(404, 'not_found', 'loan ' + id + ' not found');
        if (l.status === 'returned') ctx.fail(409, 'invalid_state', 'loan ' + id + ' is already returned');
        if (l.status === 'overdue') ctx.fail(409, 'loan_overdue', 'loan ' + id + ' is overdue and cannot be renewed');
        const member = ctx.db.get('member', l.member_id);
        if (member.status === 'suspended') ctx.fail(409, 'member_suspended', 'member ' + member.id + ' is suspended');
        if (l.renewals >= 2) ctx.fail(409, 'renewal_limit', 'loan ' + id + ' has reached the renewal limit');
        const updated = ctx.db.update('loan', id, { due_at: ctx.time.plus(l.due_at, '14d'), renewals: l.renewals + 1 });
        return { status: 200, body: updated };
      }
  pay_fine:
    method: POST
    path: /loans/{id}/pay_fine
    description: Pay the fine of a returned loan in full.
    input: {}
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const l = ctx.db.get('loan', id);
        if (l === null) ctx.fail(404, 'not_found', 'loan ' + id + ' not found');
        if (l.status !== 'returned' || l.fine_cents <= 0 || l.fine_paid) ctx.fail(409, 'no_fine_due', 'loan ' + id + ' has no payable fine');
        const updated = ctx.db.update('loan', id, { fine_paid: true });
        return { status: 200, body: updated };
      }
jobs:
  accrue_overdue:
    description: Hourly. Active loans past due become overdue. Overdue loans carry 25 cents per full day overdue, capped at 2000.
    every: 1h
    run: |-
      (ctx) => {
        const now = ctx.now();
        for (const status of ['active', 'overdue']) {
          for (const l of ctx.db.list('loan', { where: { status } })) {
            const mins = ctx.time.minutesBetween(l.due_at, now);
            if (mins <= 0) continue;
            const fine = Math.min(2000, Math.floor(mins / 1440) * 25);
            if (l.status === 'active') ctx.db.update('loan', l.id, { status: 'overdue', fine_cents: fine });
            else if (l.fine_cents !== fine) ctx.db.update('loan', l.id, { fine_cents: fine });
          }
        }
      }
